import React from 'react';
import {
  Button,
  ButtonVariant,
  Text,
  Box,
  ButtonSize,
  BoxFlexDirection,
  Modal,
  ModalBody,
  ModalFooter,
  ModalHeader,
  ModalOverlay,
  ModalContent,
} from '@metamask/design-system-react';
import { useI18nContext } from '../../../hooks/useI18nContext';
import { PermissionItem } from './permission-item';
import { DisconnectAllGatorPermissionsModalProps } from './types';

export const DisconnectAllGatorPermissionsModal = ({
  isOpen,
  onClose,
  onSkip,
  onRemoveAll,
  permissions = [],
}: DisconnectAllGatorPermissionsModalProps) => {
  const t = useI18nContext();

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      data-testid="disconnect-permissions-modal"
    >
      <ModalOverlay />
      <ModalContent>
        <ModalHeader
          onClose={onClose}
          closeButtonProps={{ ariaLabel: t('close') }}
        >
          {t('otherPermissionsOnSiteTitle')}
        </ModalHeader>
        <ModalBody className="px-0">
          <Box padding={4}>
            <Text>{t('otherPermissionsOnSiteDescription')}</Text>
          </Box>
          {permissions.length > 0 && (
            <Box>
              {permissions.map((permission, index) => {
                return (
                  <PermissionItem
                    key={`${permission.chainId}-${permission.permissionType}-${index}`}
                    permission={permission}
                  />
                );
              })}
            </Box>
          )}
        </ModalBody>
        <ModalFooter>
          <Box flexDirection={BoxFlexDirection.Row} gap={2}>
            <Button
              onClick={onSkip}
              variant={ButtonVariant.Secondary}
              size={ButtonSize.Lg}
              data-testid="skip-disconnect-permissions"
              isFullWidth
            >
              {t('skip')}
            </Button>
            <Button
              onClick={onRemoveAll}
              variant={ButtonVariant.Primary}
              size={ButtonSize.Lg}
              isDanger
              data-testid="remove-all-disconnect-permissions"
              isFullWidth
            >
              {t('removeAll')}
            </Button>
          </Box>
        </ModalFooter>
      </ModalContent>
    </Modal>
  );
};
